function maxAverageOfPath(cost) {
    const N = cost.length;
    const dp = new Array(N).fill().map(() => new Array(N).fill(0));

    // Initialize the DP table
    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            if (i === 0 && j === 0) {
                dp[i][j] = cost[i][j];
            } else {
                dp[i][j] = Math.max(
                    cost[i][j] + dp[i - 1][j],
                    cost[i][j] + dp[i][j - 1]
                );
            }
        }
    }

    // Calculate the maximum average
    let maxAverage = -Infinity;
    let totalCost = 0;
    let count = 0;

    // Backtrack to find the path with the maximum average
    function backtrack(i, j) {
        if (i === N - 1 && j === N - 1) {
            totalCost += dp[i][j];
            count++;
            maxAverage = Math.max(maxAverage, totalCost / count);
            return;
        }

        if (i < N - 1) {
            totalCost += dp[i][j];
            count++;
            backtrack(i + 1, j);
            totalCost -= dp[i][j];
            count--;
        }

        if (j < N - 1) {
            totalCost += dp[i][j];
            count++;
            backtrack(i, j + 1);
            totalCost -= dp[i][j];
            count--;
        }
    }

    backtrack(0, 0);

    return maxAverage;
}

function maxAverageOfPath(cost){
  const N = cost.length;
  const dp = Array.from({length: N}, () => Array(N).fill(0));

  // Fill the dp array from bottom to top and right to left
  for (let i = N - 1; i >= 0; i--) {
    for (let j = N - 1; j >= 0; j--) {
      if (i === N - 1 && j === N - 1) {
        dp[i][j] = cost[i][j];
      } else {
        const right = j + 1 < N ? dp[i][j + 1] : 0;
        const down = i + 1 < N ? dp[i + 1][j] : 0;
        dp[i][j] = cost[i][j] + Math.max(right, down);
      }
    }
  }

  // The maximum average path will be the maximum value in the bottom-right cell
  return dp[0][0] / (N * N);
}

