    if (index >= n || k >= n) {
        return 0;
    }

    let maxSum = a[index];
    for (let i = index + 1; i < n; i++) {
        if (a[i] > a[index]) {
            maxSum = Math.max(maxSum, max_sum_increasing_subseq(a, n, i, k) + a[i]);
