    }

    return maxSum;
}

function max_sum_increasing_subseq(a, n, index, k) {
    // Initialize a 2D array to store the maximum sum of increasing subsequence including the kth element
    const dp = Array.from({ length: n }, () => Array.from({ length: k + 1 }, () => -Infinity));

    // Base case: If the index is 0, the maximum sum is the value at the current index
    dp[0][0] = a[0];

    // Fill the dp array
    for (let i = 1; i < n; i++) {
        for (let j = 0; j <= k; j++) {
            // If the current element is greater than the previous element and the index is not k, update the dp value
            if (j === 0 || a[i] > a[i - 1]) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i - 1][j - 1] + a[i]);
            }
            // Update the dp value if the current element is greater than the previous element and the index is k
            if (j === k && a[i] > a[i - 1]) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i - 1][j - 1] + a[i]);
            }
        }
    }

    // The maximum sum of increasing subsequence including the kth element is stored in dp[n - 1][k]
    return dp[n - 1][k];
}

