function rgb_to_hsv(r, g, b) {
    let max = Math.max(r, g, b);
    let min = Math.min(r, g, b);
    let delta = max - min;

    let h, s, v;

    if (delta === 0) {
        h = 0;
        s = 0;
        v = max;
    } else {
        s = delta / max;

        const rNorm = (max - r) / delta;
        const gNorm = (max - g) / delta;
        const bNorm = (max - b) / delta;

        if (r === max) {
            h = gNorm - bNorm;
        } else if (g === max) {
            h = 2 + rNorm - bNorm;
        } else if (b === max) {
            h = 4 + gNorm - rNorm;
        }

        h /= 6;
        if (h < 0) h += 1;
    }

    return [h, s, v];
}

function rgb_to_hsv(r, g, b) {
  // Normalize RGB values to the range [0, 1]
  let rNorm = r / 255;
  let gNorm = g / 255;
  let bNorm = b / 255;

  // Calculate the maximum and minimum values
  let max = Math.max(rNorm, gNorm, bNorm);
  let min = Math.min(rNorm, gNorm, bNorm);

  // Calculate the difference between max and min
  let delta = max - min;

  // Calculate the hue
  let hue;
  if (delta === 0) {
    hue = 0;
  } else if (max === rNorm) {
    hue = (60 * ((gNorm - bNorm) / delta)) % 360;
  } else if (max === gNorm) {
    hue = (60 * ((bNorm - rNorm) / delta)) + 120;
  } else if (max === bNorm) {
    hue = (60 * ((rNorm - gNorm) / delta)) + 240;
  }

  // Calculate the saturation
  let saturation;
  if (max === 0) {
    saturation = 0;
  } else {
    saturation = (delta / max) * 100;
  }

  // Calculate the value
  let value = max * 100;

  return [hue, saturation, value];
}

