function max_sum(arr) {
  const n = arr.length;
  const dp = new Array(n).fill(0);
  const dp_desc = new Array(n).fill(0);

  // Calculate the maximum sum of increasing subsequence
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < i; j++) {
      if (arr[i] > arr[j]) {
        dp[i] = Math.max(dp[i], dp[j] + arr[i]);
      }
    }
  }

  // Calculate the maximum sum of decreasing subsequence
  for (let i = n - 1; i >= 0; i--) {
    for (let j = i + 1; j < n; j++) {
      if (arr[i] > arr[j]) {
        dp_desc[i] = Math.max(dp_desc[i], dp_desc[j] + arr[i]);
      }
    }
  }

  // Find the maximum sum of bitonic subsequence
  let max_sum = 0;
  for (let i = 0; i < n; i++) {
    max_sum = Math.max(max_sum, dp[i] + dp_desc[i] - arr[i]);
  }

  return max_sum;
}

function max_sum(arr) {
  let n = arr.length;
  let dp = new Array(n).fill(0);
  let dpRev = new Array(n).fill(0);
  let maxSum = 0;

  // Calculate the maximum sum of increasing subsequences
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < i; j++) {
      if (arr[i] > arr[j]) {
        dp[i] = Math.max(dp[i], dp[j] + arr[i]);
      }
    }
    maxSum = Math.max(maxSum, dp[i]);
  }

  // Calculate the maximum sum of decreasing subsequences
  for (let i = n - 1; i >= 0; i--) {
    for (let j = i + 1; j < n; j++) {
      if (arr[i] > arr[j]) {
        dpRev[i] = Math.max(dpRev[i], dpRev[j] + arr[i]);
      }
    }
    maxSum = Math.max(maxSum, dpRev[i]);
  }

  // Calculate the maximum sum of bitonic subsequences
  for (let i = 0; i < n; i++) {
    maxSum = Math.max(maxSum, dp[i] + dpRev[i] - arr[i]);
  }

  return maxSum;
}

