function find_first_occurrence(A, x){
    let left = 0;
    let right = A.length - 1;

    while (left <= right) {
        let mid = Math.floor((left + right) / 2);

        if (A[mid] === x) {
            // If the element is found, move the right pointer to the left
            right = mid - 1;
        } else if (A[mid] < x) {
            // If the element is less than x, move the left pointer to the right
            left = mid + 1;
        } else {
            // If the element is greater than x, move the right pointer to the left
            right = mid - 1;
        }
    }

    // If the element is not found, return -1
    return left;
}

