function rearrange_bigger(n) {
    // Convert the number to an array of its digits
    const digits = Array.from(String(n), Number);

    // Find the first digit from the right that is smaller than the digit immediately to its right
    let i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such digit is found, return -1
    if (i === -1) {
        return -1;
    }

    // Find the smallest digit to the right of the found digit that is larger than it
    let j = digits.length - 1;
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }

    // Swap the found digits
    [digits[i], digits[j]] = [digits[j], digits[i]];

    // Sort the digits to the right of the swapped digit in ascending order
    digits.splice(i + 1).sort((a, b) => a - b);

    // Convert the array of digits back to a number
    return parseInt(digits.join(''), 10);
}

function rearrange_bigger(n){
  // Convert the number to an array of digits
  const digits = Array.from(String(n), Number);

  // Find the index of the first digit that is smaller than the digit immediately after it
  let i = digits.length - 2;
  while (i >= 0 && digits[i] >= digits[i + 1]) {
    i--;
  }

  // If no such digit is found, the number is the largest possible permutation
  if (i === -1) {
    return -1;
  }

  // Find the smallest digit to the right of the found digit that is larger than it
  let j = digits.length - 1;
  while (j > i && digits[j] <= digits[i]) {
    j--;
  }

  // Swap the found digits
  [digits[i], digits[j]] = [digits[j], digits[i]];

  // Sort the digits to the right of the swapped digit in descending order
  digits.splice(i + 1).sort((a, b) => b - a);

  // Combine the digits back into a number
  return parseInt(digits.join(''));
}

